INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'sampling_points_6', 'Probenahmepunkte (je Punkt: Kennung, Koordinate, Tiefen, Ortstyp nach §7 mit Prüfungen, Homogenität, Mischung, Position ≥ 30 cm)', 'json', NULL, false, '§5.1.1, §5.1.2, §5.1.4, §7.1–§7.6, §15', 'Plan 3: Zeilen je Probenahmepunkt mit den §7-Prüfungen je Ortstyp (Brücke: Position / Prüfungen a–d; Vadeo / Ufer: Warnschutz; Eis: Eissicherheit) und dem §7.1-Abstand (≥ 30 cm über Sohle, ≥ 30 cm unter Oberfläche, S7_1); Anzahl → sampling_point_count_calc (ISO-5667-6-02-D1), Zeilen mit nicht erfüllter Position → points_depth_fail (-D2). Die Einzelskalare sampling_point_count / sampling_depths (-02), reference_coordinate / homogeneity_status / mixing_* (-03), sampling_location_type / bridge_* / ppe_high_visibility / sampling_depth_below_surface / height_above_bed (-07) bleiben (iso5667_6-D-4 … D-16); ein Gate auf points_depth_fail ist STAGED (iso5667_6-G-9).', 'imported_unverified', 'Cuando sea posible, las ubicaciones del sitio de muestreo deberían ser definidas por una coordenada
de referencia, de acuerdo con el sistema de coordenadas internacional que se encuentra en
ISO 19112[9]. — Generalmente, se debería evitar el muestreo en o cerca de la superficie, en el fondo, en la orilla, en
áreas estancadas y estanques. Es necesario tener especial precaución de no perturbar los sedimentos
del fondo y evitar películas no representativas en la superficie. Siempre que sea posible, las muestras
obtenidas de posiciones al menos 30 cm por encima del fondo de un curso de agua y a una distancia
similar debajo de la superficie, suelen ser satisfactorias.', 'register', '{"title":"Probenahmepunkte (puntos de muestreo, §5.1 / §7)","subtitle":"Je Probenahmepunkt eine Zeile: Kennung, Referenzkoordinate (§5.1.1), Tiefen, Ortstyp nach §7 mit den zugehörigen Prüfungen (Brücke §7.2, Vadeo/Ufer §7.3–7.4 + §15, Eis §7.6 + §15), Homogenität (§5.1.4), Mischung (§5.1.2), Position ≥ 30 cm über Sohle / unter Oberfläche (§7.1)","add_label":"+ Probenahmepunkt","placement":"section","columns":[{"key":"kennung","label":"Kennung / ID","type":"text","required":true,"aria_label":"Kennung des Probenahmepunkts"},{"key":"coordinate","label":"Referenzkoordinate","type":"text","aria_label":"Coordenada de referencia (ISO 19112)"},{"key":"depths","label":"Probenahmetiefen","type":"text","aria_label":"Probenahmetiefen des Punkts"},{"key":"location_type","label":"Ortstyp (§7)","type":"enum","required":true,"options":["bridge","in_watercourse_wading","bank","boat","under_ice"],"option_labels":{"bridge":"desde puentes (§7.2)","in_watercourse_wading":"en el curso de agua — vadeo (§7.3)","bank":"desde la orilla (§7.4)","boat":"desde embarcaciones (§7.5)","under_ice":"bajo hielo (§7.6)"},"discriminator":true,"aria_label":"Probenahme-Ortstyp"},{"key":"bridge_position","label":"Position am Puente","type":"enum","options":["upstream","downstream"],"option_labels":{"upstream":"aguas arriba del puente (bevorzugt)","downstream":"aguas abajo del puente"},"visible_when":"location_type == ''bridge''","aria_label":"Aguas arriba o aguas abajo del puente"},{"key":"bridge_checks","label":"Prüfungen a) – d) erfüllt","type":"boolean","visible_when":"location_type == ''bridge''","aria_label":"Brückenprüfungen a) bis d) erfüllt (§7.2)"},{"key":"ppe_high_visibility","label":"Warnschutz / Schwimmweste","type":"boolean","visible_when":"location_type IN {in_watercourse_wading, bank}","aria_label":"Warnschutzkleidung und Schwimmhilfe verwendet (§7.1 / §15)"},{"key":"ice_safety","label":"Eissicherheit geprüft","type":"boolean","visible_when":"location_type == ''under_ice''","aria_label":"Eisdicke / Tragfähigkeit und Ausbildung geprüft (§7.6 / §15)"},{"key":"homogeneity_status","label":"Homogenität (§5.1.4)","type":"enum","options":["homogeneous","non_homogeneous","untested"],"option_labels":{"homogeneous":"distribuidos homogéneamente","non_homogeneous":"distribución no homogénea","untested":"sin pruebas (ungeprüft)"},"aria_label":"Homogenitätsstatus des Punkts"},{"key":"mixing_relevant","label":"Mischung relevant","type":"boolean","aria_label":"Mischung für das Probenahmeregime relevant (§5.1.2)"},{"key":"mixing_dimension","label":"Mischungsdimension","type":"enum","options":["vertical","lateral","longitudinal"],"option_labels":{"vertical":"a) verticalmente","lateral":"b) lateralmente","longitudinal":"c) longitudinalmente"},"visible_when":"mixing_relevant == true","aria_label":"Mischungsdimension (§5.1.2 a–c)"},{"key":"vertical_mixing_distance","label":"Vertikale Mischdistanz","type":"number","unit":"m","min":0,"visible_when":"mixing_dimension == ''vertical''","aria_label":"Vertikale Mischdistanz in Metern"},{"key":"depth_below_surface_cm","label":"Tiefe unter Oberfläche","type":"number","unit":"cm","min":0,"aria_label":"Probenahmetiefe unter der Oberfläche in cm"},{"key":"height_above_bed_cm","label":"Höhe über Sohle","type":"number","unit":"cm","min":0,"aria_label":"Höhe über der Gewässersohle in cm"},{"key":"depth_ok","label":"§7.1 Position","type":"derived","expr":"if(depth_below_surface_cm IS NULL OR height_above_bed_cm IS NULL, 0, if(depth_below_surface_cm >= lookup(''S7_1'', ''general'', ''depth_below_surface_min_cm'') AND height_above_bed_cm >= lookup(''S7_1'', ''general'', ''height_above_bed_min_cm''), 1, 0))","display":"badge","value_labels":{"0":"§7.1 Position nicht erfüllt oder nicht eingetragen (Anhaltswert, iso5667_6-J-1)","1":"§7.1 ≥ 30 cm über Sohle und unter Oberfläche (Anhaltswert, iso5667_6-J-1)"}}],"footer":["sampling_point_count_calc","points_depth_fail"],"note":"obtenidas de posiciones al menos 30 cm por encima del fondo de un curso de agua y a una distancia\nsimilar debajo de la superficie, suelen ser satisfactorias. Die Spalten nach dem Ortstyp zeigen nur die Prüfungen des gewählten §7-Abschnitts; die Einzelfelder derselben Angaben auf ISO-5667-6-02 / -03 / -07 bleiben bis zur Ratifizierung (iso5667_6-D-4 … D-16). Die Lesarten „alrededor de 30 cm“ (§7.3–7.5) und „dentro de 30 cm“ (§8.1) sind iso5667_6-J-1."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'sampling_points_6') AND w.code = 'ISO-5667-6-02' AND s.code = 'ISO-5667-6';
