INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'heterogeneity_samples', 'Heterogenitätsproben (je Probe: Nr., Durchfluss, Determinante, Messwert; §5.1.4)', 'json', NULL, false, '§5.1.4', 'Plan 3: Zeilen je Heterogenitätsprobe; Anzahl → heterogeneity_samples_count_calc (ISO-5667-6-03-D1), Vergleich mit den „aproximadamente seis“ (S5_1_4, als ≥ 6 wie CR-008) → heterogeneity_samples_ok (-D2), Spannweite max − min → heterogeneity_spread (-D3). Die Einzelfelder heterogeneity_samples_count / heterogeneity_test_flows / heterogeneity_determinant bleiben (iso5667_6-D-17 … D-19); IF-Guard von CR-008 STAGED (iso5667_6-G-8).', 'imported_unverified', 'Si existe alguna posibilidad de que haya una distribución no homogénea de los determinantes de
interés en el sitio seleccionado, se deberían realizar pruebas experimentales sobre la naturaleza y
magnitud de cualquier heterogeneidad en las tres dimensiones. Si dichas pruebas muestran que los
determinantes están distribuidos homogéneamente, cualquier punto de muestreo es suficiente. De lo
contrario, se debería buscar otro sitio en el que los determinantes estén distribuidos homogéneamente. — la cantidad de trabajo que esto implica. La parte de la sección transversal a través de la cual una gran
parte (alrededor del 90%) de los pasos totales de flujo, se decide aproximadamente. Dentro de esa
parte, se deberían tomar aproximadamente seis muestras repartidas a través de la parte. Los grandes
ríos podrían requerir más muestras laterales y verticales. Para determinar si algunas diferencias
aparentes entre las muestras son provocadas por la distribución no homogénea o por errores analíticos,
es necesario un análisis estadístico de los resultados. Todas esas muestras deberían ser recogidas
lo más cercanas al mismo tiempo como sea posible, para evitar los efectos de la variación temporal.
De preferencia, las muestras se deberían tomar de al menos tres caudales correspondientes a lo más
cerca posible de los flujos mínimos, modales y máximos esperados durante el período de las pruebas.', 'register', '{"title":"Heterogenitätsproben (§5.1.4)","subtitle":"Je Probe eine Zeile: Nr., Durchfluss (caudal), Determinante, Messwert — etwa sechs Proben über den Querschnittsteil mit ≈ 90 % des Durchflusses, bei mindestens drei Durchflüssen (Minimum, Modal, Maximum)","add_label":"+ Probe","placement":"section","columns":[{"key":"sample_no","label":"Nr.","type":"number","required":true,"min":1,"aria_label":"Probennummer"},{"key":"flow","label":"Durchfluss (caudal)","type":"number","required":true,"min":0,"aria_label":"Durchfluss bei der Probe"},{"key":"determinant","label":"Determinante","type":"text","datalist":["pH","conductividad","cloro","amoníaco","sólidos en suspensión","oxígeno disuelto","color","hierro","clorofila","carbono orgánico total","demanda bioquímica de oxígeno"],"aria_label":"Geprüfte Determinante"},{"key":"value","label":"Messwert","type":"number","required":true,"aria_label":"Messwert der Determinante"}],"footer":["heterogeneity_samples_count_calc","heterogeneity_samples_ok","heterogeneity_spread"],"note":"la cantidad de trabajo que esto implica. La parte de la sección transversal a través de la cual una gran\nparte (alrededor del 90%) de los pasos totales de flujo, se decide aproximadamente. Dentro de esa\nparte, se deberían tomar aproximadamente seis muestras repartidas a través de la parte. Los grandes De preferencia, las muestras se deberían tomar de al menos tres caudales correspondientes a lo más\ncerca posible de los flujos mínimos, modales y máximos esperados durante el período de las pruebas. Die Zahl der verschiedenen Durchflüsse (≥ 3) ist aus den Zeilen nicht berechenbar — kein distinct in der Ausdruckssprache (iso5667_6-F-1); heterogeneity_test_flows bleibt Handangabe. Die Spannweite (max − min) ist nur je Determinante sinnvoll (iso5667_6-J-3)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'heterogeneity_samples') AND w.code = 'ISO-5667-6-03' AND s.code = 'ISO-5667-6';
