SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'heterogeneity_samples_ok', 'Etwa sechs Proben erreicht (1 = ≥ 6, 0 = weniger)', 'number', NULL, false, '§5.1.4', 'Plan 3: Ausgabe der Gleichung ISO-5667-6-03-D2 — Anzahl der Zeilen ≥ S5_1_4.samples_approx (6; „aproximadamente seis muestras“, iso5667_6-J-2); Gate STAGED (iso5667_6-G-8).', 'imported_unverified', 'la cantidad de trabajo que esto implica. La parte de la sección transversal a través de la cual una gran
