INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'heterogeneity_spread', 'Spannweite der Messwerte (max − min) über die Heterogenitätsproben', 'number', NULL, false, '§5.1.4', 'Plan 3: Ausgabe der Gleichung ISO-5667-6-03-D3 (max_rows − min_rows über heterogeneity_samples.value); Hilfsgröße für die statistische Beurteilung („es necesario un análisis estadístico de los resultados“) — nur je Determinante sinnvoll (iso5667_6-J-3); homogeneity_status bleibt die Entscheidung des Ingenieurs.', 'imported_unverified', 'parte, se deberían tomar aproximadamente seis muestras repartidas a través de la parte. Los grandes
ríos podrían requerir más muestras laterales y verticales. Para determinar si algunas diferencias
aparentes entre las muestras son provocadas por la distribución no homogénea o por errores analíticos,
es necesario un análisis estadístico de los resultados. Todas esas muestras deberían ser recogidas
lo más cercanas al mismo tiempo como sea posible, para evitar los efectos de la variación temporal.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'heterogeneity_spread') AND w.code = 'ISO-5667-6-03' AND s.code = 'ISO-5667-6';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'travel_time_runs', 'Fließzeitmessungen (je Messung: Durchfluss, Methode, Fließzeit; §5.1.3 ≥ 5 Durchflüsse)', 'json', NULL, false, '§5.1.3', 'Plan 3: Zeilen je Fließzeitmessung; Anzahl → travel_time_flows_count_calc (ISO-5667-6-04-D1), Vergleich mit den fünf des §5.1.3 (S5_1_3.flows_min) → travel_time_flows_ok (-D2), die gedruckte Extrapolationsgrenze 10 % → travel_time_extrapolation_max (-D3). Die Einzelskalare bleiben (iso5667_6-D-20 … D-22); IF-Guard von CR-009 STAGED (iso5667_6-G-3).', 'imported_unverified', 'Al determinar el tiempo de viaje, se debería utilizar uno de los tres métodos principales,
específicamente el uso de flotadores de superficie (ver ISO 748), el uso de trazadores
(ver ISO 9555), la medición del caudal con conocimiento de las áreas de sección transversal
(ver ISO 748 e ISO 1070). — Las mediciones se deberían realizar en un mínimo de cinco caudales diferentes y los tiempos de
viaje resultantes trazados en relación con los caudales correspondientes, permitiendo así que
se obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la
extrapolación fuera del 10% de un valor de medición del caudal puede proporcionar información
incorrecta sobre el tiempo de viaje.', 'register', '{"title":"Fließzeitmessungen (tiempo de viaje, §5.1.3)","subtitle":"Je Messung eine Zeile: Durchfluss, Methode (flotadores de superficie / trazadores / medición del caudal), Fließzeit — Messungen bei mindestens fünf verschiedenen Durchflüssen","add_label":"+ Messung","placement":"section","columns":[{"key":"flow","label":"Durchfluss (caudal)","type":"number","required":true,"min":0,"aria_label":"Durchfluss der Fließzeitmessung"},{"key":"method","label":"Methode","type":"enum","options":["surface_floats","tracers","discharge_cross_section"],"option_labels":{"surface_floats":"flotadores de superficie (ISO 748)","tracers":"trazadores (ISO 9555)","discharge_cross_section":"medición del caudal con áreas de sección transversal (ISO 748 / ISO 1070)"},"aria_label":"Methode der Fließzeitmessung"},{"key":"travel_time_min","label":"Fließzeit","type":"number","unit":"min","required":true,"min":0,"aria_label":"Gemessene Fließzeit in Minuten"}],"footer":["travel_time_flows_count_calc","travel_time_flows_ok","travel_time_extrapolation_max"],"note":"Las mediciones se deberían realizar en un mínimo de cinco caudales diferentes y los tiempos de\nviaje resultantes trazados en relación con los caudales correspondientes, permitiendo así que\nse obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la\nextrapolación fuera del 10% de un valor de medición del caudal puede proporcionar información\nincorrecta sobre el tiempo de viaje. Die Einzelfelder travel_time_method / travel_time_flows_count bleiben (iso5667_6-D-20 / D-21); CR-009 liest heute den Skalar — Umstellung STAGED (iso5667_6-G-3)."}'::jsonb, NULL, 'travel_time_required == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'travel_time_runs') AND w.code = 'ISO-5667-6-04' AND s.code = 'ISO-5667-6';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'travel_time_flows_count_calc', 'Anzahl Fließzeitmessungen (aus dem Register)', 'number', NULL, false, '§5.1.3', 'Plan 3: Ausgabe der Gleichung ISO-5667-6-04-D1 (count_rows über travel_time_runs); Zwilling des Eingabefelds travel_time_flows_count (iso5667_6-D-21).', 'imported_unverified', 'Las mediciones se deberían realizar en un mínimo de cinco caudales diferentes y los tiempos de
viaje resultantes trazados en relación con los caudales correspondientes, permitiendo así que
se obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la
