FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'increment_total_time_calc') AND w.code = 'ISO-5667-6-09' AND s.code = 'ISO-5667-6';
