SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'bed_roughness_hint', 'Sohlenbeschaffenheit nach dem Anexo-A-Beispiel (fondo muy irregular / fondo muy liso)', 'enum', NULL, false, 'Anexo A EJEMPLO', 'Plan 3: Treiber des Anhaltswerts c_hint (ANNEXA: 15 bei sehr unregelmäßiger, 50 bei sehr glatter Sohle — die beiden gedruckten Extremwerte des Beispiels); der Chézy-Koeffizient c bleibt Eingabe im gedruckten Bereich 15 < c < 50 (SR-2).', 'imported_unverified', 'c    = coeficiente de Chézy para el tramo (15 < c < 50); — EJEMPLO Considerar dos cursos de agua, ambos de 5 m de ancho y 1 m de profundidad, pero con valores extremos
del coeficiente de Chézy; uno de 15 (fondo muy irregular, es decir, el curso de agua es muy rápido y turbulento) y el
otro de 50 (fondo muy liso, es decir, un curso de agua muy tranquilo, de movimiento lento). Cuando se calcula según
Ecuación (A.1), los antiguos confines completan la homogeneidad después de 83 m, mientras que el último no es
homogéneo hasta que haya recorrido 683 m.', 'select_one', NULL, NULL, 'mixing_relevant == true', '[{"value":"muy_irregular","label_de":"fondo muy irregular (sehr unregelmäßige Sohle — Beispiel c = 15)","order_index":0},{"value":"liso","label_de":"fondo muy liso (sehr glatte Sohle — Beispiel c = 50)","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bed_roughness_hint') AND w.code = 'ISO-5667-6-13' AND s.code = 'ISO-5667-6';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'c_hint', 'Chézy-Koeffizient nach dem Anexo-A-Beispiel (Anhaltswert; c bleibt Eingabe, 15 < c < 50)', 'number', NULL, false, 'Anexo A EJEMPLO', 'Plan 3: aus der Sohlenbeschaffenheit gefüllt (anhaltswert — „(informativo)“, „se puede calcular aproximadamente“); das Eingabefeld c (Gleichung A.1) bleibt der Wert des Ingenieurs — die Norm druckt einen Bereich, keinen Punkt (SR-2); Ecuación (A.1) selbst wird nicht neu gefasst (iso5667_6-U-1).', 'imported_unverified', 'c    = coeficiente de Chézy para el tramo (15 < c < 50); — EJEMPLO Considerar dos cursos de agua, ambos de 5 m de ancho y 1 m de profundidad, pero con valores extremos
del coeficiente de Chézy; uno de 15 (fondo muy irregular, es decir, el curso de agua es muy rápido y turbulento) y el
otro de 50 (fondo muy liso, es decir, un curso de agua muy tranquilo, de movimiento lento). Cuando se calcula según
Ecuación (A.1), los antiguos confines completan la homogeneidad después de 83 m, mientras que el último no es
homogéneo hasta que haya recorrido 683 m.', 'lookup_fill', '{"source_label":"Anexo A EJEMPLO (Anhaltswert)"}'::jsonb, '{"table_code":"ANNEXA","role":"value","keys":[{"column":"roughness","from_symbol":"bed_roughness_hint"}],"value":"c_example"}'::jsonb, 'mixing_relevant == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'c_hint') AND w.code = 'ISO-5667-6-13' AND s.code = 'ISO-5667-6';
COMMIT;
